import hashlib, random

def h(header: bytes, nonce: int) -> int:
    d = hashlib.sha256(hashlib.sha256(header + nonce.to_bytes(8, "little")).digest()).digest()
    return int.from_bytes(d, "big")

T_BLOCK = 2**256 >> 20   # target "vero" (serve ~2^20 hash per un blocco)
T_SHARE = 2**256 >> 10   # target delle share: 1024 volte più facile

# tre miner con potenza diversa: numero di hash per "tick"
potenza = {"AAA": 5, "BBB": 3, "CCC": 2}
header = b"pool-template-block-42"
rnd = random.Random(7)
share = {m: 0 for m in potenza}
hash_fatti = {m: 0 for m in potenza}
blocco = None
while blocco is None:
    for m, hp in potenza.items():
        for _ in range(hp):
            nonce = rnd.getrandbits(64)
            v = h(header + m.encode(), nonce)
            hash_fatti[m] += 1
            if v < T_SHARE:
                share[m] += 1
                if v < T_BLOCK:
                    blocco = (m, nonce)
tot_share = sum(share.values())
tot_hash = sum(hash_fatti.values())
print("blocco trovato da:", blocco[0])
for m in potenza:
    print(f"{m}: hash={hash_fatti[m]:7d} ({hash_fatti[m]/tot_hash:.2%})  share={share[m]:4d} ({share[m]/tot_share:.2%})")
print("hash totali / share totali =", round(tot_hash / tot_share), "(atteso 1024 = 2^10)")

