codeExercises.solution:
import random

def formula(a, g):
    """Ricavo relativo del pool egoista (Eyal & Sirer 2014)."""
    num = a * (1 - a)**2 * (4*a + g*(1 - 2*a)) - a**3
    den = 1 - a * (1 + (2 - a) * a)
    return num / den

def simula(a, g, eventi=1_000_000, seed=3):
    rnd = random.Random(seed)
    priv = 0          # vantaggio della catena privata
    fork = False      # stato 0': due rami di lunghezza 1 in gara
    rS = rH = 0       # blocchi finiti nella catena principale
    for _ in range(eventi):
        if rnd.random() < a:                 # blocco trovato dal pool egoista
            if fork:
                rS += 2; fork = False        # vince la gara con 2 blocchi
            else:
                priv += 1
        else:                                # blocco trovato dagli onesti
            if fork:
                if rnd.random() < g: rS += 1; rH += 1   # onesti estendono il ramo egoista
                else: rH += 2                            # onesti estendono il proprio ramo
                fork = False
            elif priv == 0:
                rH += 1
            elif priv == 1:
                priv = 0; fork = True        # pubblica: gara 1 contro 1
            elif priv == 2:
                rS += 2; priv = 0            # pubblica tutto e vince
            else:
                rS += 1; priv -= 1           # pubblica un blocco, resta avanti
    return rS / (rS + rH)

for a in (0.20, 0.25, 0.30, 0.35, 0.40):
    print(f"alpha={a:.2f}  gamma=0: formula={formula(a,0):.4f} sim={simula(a,0):.4f}"
          f"  | gamma=0.5: formula={formula(a,0.5):.4f}")
print("soglia gamma=0  :", round(formula(1/3, 0), 4), "(= 1/3 alla soglia)")
print("soglia gamma=0.5:", round(formula(1/4, 0.5), 4), "(= 1/4 alla soglia)")
